import {intervals,LABELS} from './validation.js';
export const SCREEN_RULE={dwell:.5};
export function screenTrialRecords(data){return (data.trials??[]).filter(t=>['screenInside','screenOutside'].includes(t.kind)).map(t=>{
 const expected=t.instruction.screen,end=t.end??data.duration,rule=t.screenRule??SCREEN_RULE,spans=[],directions=new Map(),heads=new Map();let run=0,longest=0,previous=null,firstQualifying=null;
 for(const s of intervals(data)){const start=Math.max(s.start,t.start),finish=Math.min(s.end,end);if(finish<=start)continue;const dt=finish-start;
 if(s.screen===expected){if(spans.length&&Math.abs(spans.at(-1).end-start)<1e-7)spans.at(-1).end=finish;else spans.push({start,end:finish});run=(previous!==null&&Math.abs(previous-start)<1e-7?run:0)+dt;longest=Math.max(longest,run);if(firstQualifying===null&&run+1e-8>=rule.dwell)firstQualifying=start+dt-run;}
 else run=0;previous=finish;
 for(const [field,map] of [['direction',directions],['head',heads]]){const state=s[field]??'UNKNOWN';map.set(state,(map.get(state)??0)+dt);}
 }
 const dominant=map=>{const rows=[...map].sort((a,b)=>b[1]-a[1]);return !rows.length||rows[1]&&Math.abs(rows[0][1]-rows[1][1])<1e-8?'UNKNOWN':rows[0][0];};
 return {...t,expected,firstStart:spans[0]?.start??null,lastEnd:spans.at(-1)?.end??null,totalSeconds:spans.reduce((s,e)=>s+e.end-e.start,0),episodes:spans,longestSeconds:longest,detected:t.end==null||t.interrupted?null:firstQualifying!==null,responseSeconds:firstQualifying===null?null:firstQualifying-t.start,dwell:rule.dwell,gazeDirection:dominant(directions),headDirection:dominant(heads)};
 });}
export function simpleSummary(data){const trials=screenTrialRecords(data);return ['INSIDE','OUTSIDE'].map(state=>{const kind=state==='INSIDE'?'screenInside':'screenOutside',items=trials.filter(t=>t.expected===state),planned=(data.events??[]).filter(e=>e.type==='TRIAL_RUN_START'&&e.kind===kind).reduce((n,e)=>n+e.planned,0)||items.length;return {state,planned,presented:items.length,completed:items.filter(t=>t.end!=null&&!t.interrupted).length,detected:items.filter(t=>t.detected===true).length,firstStart:items.reduce((v,t)=>t.firstStart===null?v:v===null?t.firstStart:Math.min(v,t.firstStart),null),lastEnd:items.reduce((v,t)=>t.lastEnd===null?v:v===null?t.lastEnd:Math.max(v,t.lastEnd),null),totalSeconds:items.reduce((s,t)=>s+t.totalSeconds,0),items};});}
export function simpleRows(data){const totals=new Map(simpleSummary(data).map(s=>[s.state,s]));return [['participant_id','name','session_id','mode','trial_id','expected','detected','start_s','end_s','total_gaze_s','longest_gaze_s','required_dwell_s','gaze_direction','head_direction','gaze_arrival_s','interrupted','planned_count','recognized_count'],...screenTrialRecords(data).map(t=>[data.meta.participant,data.meta.participantSnapshot?.name??'',data.meta.session,data.meta.mode,t.id,t.expected,t.detected,t.firstStart,t.lastEnd,t.totalSeconds,t.longestSeconds,t.dwell,t.gazeDirection,t.headDirection,t.responseSeconds,!!t.interrupted,totals.get(t.expected).planned,totals.get(t.expected).detected])].map(row=>row.map(v=>typeof v==='number'&&Number.isFinite(v)?Math.round(v*1e6)/1e6:v));}
const $=id=>document.getElementById(id),fmt=n=>n==null?'—':n.toFixed(2),label=k=>LABELS[k]??k;
export function renderSimple(data){$('simpleResult').hidden=!!data.referenceOnly;$('simpleName').textContent=(data.meta.participantSnapshot?.name??data.meta.participant)+' · 주시 결과'+(data.meta.mode==='demo'?' (데모)':'');$('simpleSummary').replaceChildren();$('simpleTrials').replaceChildren();let n=0;
 for(const s of simpleSummary(data)){if(!s.planned)continue;n++;const card=document.createElement('div');card.className='simple-state';const h=document.createElement('h3');h.textContent=(s.state==='INSIDE'?'화면 안 주시':'화면 밖 주시')+' · '+s.planned+'회 중 '+s.detected+'회 인식';const p=document.createElement('p');p.textContent='시작 '+fmt(s.firstStart)+'초 / 끝 '+fmt(s.lastEnd)+'초 / 총시간 '+fmt(s.totalSeconds)+'초';card.append(h,p);if(s.completed<s.planned){const note=document.createElement('small');note.textContent='완료 '+s.completed+'회 / 미완료 '+(s.planned-s.completed)+'회 (분모 유지)';card.append(note);}$('simpleSummary').append(card);
 for(const [i,t] of s.items.entries()){const tr=document.createElement('tr');for(const value of [i+1,s.state==='INSIDE'?'화면 안':'화면 밖',t.detected===null?'중단/진행 중':t.detected?'인식':'미인식',fmt(t.firstStart),fmt(t.lastEnd),fmt(t.totalSeconds),label(t.gazeDirection),label(t.headDirection)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('simpleTrials').append(tr);}
 }
 if(!n){const p=document.createElement('p');p.textContent='이 기록에는 10회 주시 테스트가 없습니다. 기존 관찰 자료는 상세 자료에서 확인할 수 있습니다.';$('simpleSummary').append(p);}
}
